def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            rich_pressure += min(float(opp.get('budget', 0.0)), 200.0)

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 2:
            return float(min(budget, 45.0))
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.5
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days == 1:
        urgency += 0.45
    urgency += scarcity * 0.8

    conservative = 16.0 + scarcity * 10.0
    pressure_bid = max(avg_prev + 2.0, highest_prev + 1.5)

    if highest_prev >= 100.0:
        if urgency < 1.0:
            bid = conservative
        else:
            bid = min(pressure_bid, 78.0)
    elif highest_prev >= 50.0:
        if urgency < 0.7:
            bid = conservative + 4.0
        else:
            bid = min(pressure_bid, 72.0)
    else:
        if urgency < 0.5:
            bid = max(22.0, avg_prev + 3.0)
        else:
            bid = max(36.0, pressure_bid)

    if rich_pressure > 250.0 and urgency >= 0.8:
        bid += 4.0

    if supply >= 23 and urgency < 1.0:
        bid *= 0.8
    elif supply <= 17:
        bid += 6.0

    if budget < 60.0:
        bid = min(bid, max(12.0, budget * 0.75))
    elif budget < 140.0:
        bid = min(bid, budget * 0.6)
    else:
        bid = min(bid, budget * 0.45)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, highest_prev + 3.0 if highest_prev > 0 else 55.0))

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids to infer aggressiveness.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    # Base urgency: if low HP or already no-water days, bid more.
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    elif my_hp <= 6:
        urgency = 0.4
    else:
        urgency = 0.25

    if my_no_water_days >= 2:
        urgency = min(1.0, urgency + 0.25)

    # Supply pressure: lower supply means fewer units; bid to secure water.
    # Map supply to [0,1] where 1 = tightest.
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        tightness = 0.5
    tightness = max(0.0, min(1.0, float(tightness)))

    # Use yesterday's highest bid to decide whether to outbid.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # If someone bid very high yesterday (likely desperation), avoid overbidding like Alex.
    # Instead, aim just above typical aggressive level.
    # Compute a target multiplier.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High desperation observed; bid moderately high but not maximal.
        target = DAILY_SALARY * (0.45 + 0.35 * urgency + 0.15 * tightness)
        # Slightly react upward if my HP is critical.
        if my_hp <= 2:
            target = DAILY_SALARY * (0.65 + 0.2 * tightness)
    else:
        # Normal/medium competition: bid around mid-high to beat Cindy-like moderate aggressors.
        target = DAILY_SALARY * (0.55 + 0.25 * urgency + 0.2 * tightness)

        # If yesterday highest bid was moderate, try to be above it by a small margin.
        if highest_prev_bid > 0:
            target = max(target, highest_prev_bid + 2.0)

    # Cap target to budget and avoid reckless spending.
    # Keep a safety reserve so we don't repeat Alex's bankruptcy pattern.
    safety_reserve = DAILY_SALARY * 0.15
    max_affordable = max(0.0, my_budget - safety_reserve)
    bid = min(my_budget, max_affordable, target)

    # If budget is low, still bid enough to prevent imminent death.
    if my_hp <= 1 and my_budget > 0:
        bid = min(my_budget, DAILY_SALARY * 0.9)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

